// ─── REPLY STALENESS DETECTOR ──────────────────────────────────────────────
//
// Finds leads where:
//   1. Reply Received = TRUE (col AA)
//   2. Reply Date = today (col AB) — reply came in today
//   3. Status is still in an outreach stage (col T) — CRM not yet updated past outreach
//   4. 2+ hours have elapsed since the reply came in
//
// Column map (crm-setup.md v2):
//   T  = Status
//   Y  = Last Contact Date
//   Z  = Next Follow-Up Date
//   AA = Reply Received (checkbox)
//   AB = Reply Date
//   AC = Reply Type
//   AD = Reply Summary
//   R  = Lead Score
//   S  = Priority Tier
//   B  = Business Name
//   E  = First Name
//   F  = Email
//   I  = City
//   C  = Industry

const items = $input.all();
const now = new Date();
const todayStr = now.toISOString().split('T')[0];
const TWO_HOURS_MS = 2 * 60 * 60 * 1000;

// Outreach stages where a reply means action is needed urgently
const OUTREACH_STAGES = new Set([
  'Contacted',
  'Follow-Up 1 Sent',
  'Follow-Up 2 Sent',
  'Follow-Up 3 Sent',
  'Replied' // Replied but no sub-status update yet
]);

const staleReplies = [];

for (const item of items) {
  const lead = item.json;

  if (!lead['Business Name'] || !lead['Email']) continue;

  const replyReceived = lead['Reply Received'] === 'TRUE' || lead['Reply Received'] === true;
  if (!replyReceived) continue;

  const replyDateStr = lead['Reply Date'];
  if (!replyDateStr) continue;

  // Only check replies received today
  const replyDate = new Date(replyDateStr);
  const replyDateOnly = replyDate.toISOString().split('T')[0];
  if (replyDateOnly !== todayStr) continue;

  // Only flag if status is still in an outreach stage
  const status = (lead['Status'] || '').trim();
  if (!OUTREACH_STAGES.has(status)) continue;

  // Check if 2+ hours have elapsed since the reply came in
  // Reply Date from Sheets is often just a date string without time;
  // if no time component, treat as start of day (conservative) — will alert
  const elapsedMs = now - replyDate;
  if (elapsedMs < TWO_HOURS_MS) continue;

  const hoursElapsed = Math.floor(elapsedMs / 3600000);
  const minutesElapsed = Math.floor((elapsedMs % 3600000) / 60000);
  const elapsedStr = hoursElapsed > 0
    ? `${hoursElapsed}h ${minutesElapsed}m`
    : `${minutesElapsed}m`;

  staleReplies.push({
    businessName:    lead['Business Name'],
    firstName:       lead['First Name'] || lead['Contact Name'] || '',
    email:           lead['Email'],
    city:            lead['City'] || '',
    industry:        lead['Industry'] || '',
    status:          status,
    replyType:       lead['Reply Type'] || '(not classified)',
    replySummary:    lead['Reply Summary'] || '(not yet logged)',
    leadScore:       lead['Lead Score'] || '',
    priorityTier:    lead['Priority Tier'] || '',
    elapsedStr
  });
}

if (staleReplies.length === 0) {
  return [{ json: { hasStaleReplies: false, count: 0, alertBody: '', subjectLine: '' } }];
}

// Sort: HOT first
const TIER_ORDER = { '🔴 HOT': 0, '🟠 WARM': 1, '🟡 COOL': 2, '⚪ COLD': 3 };
staleReplies.sort((a, b) =>
  (TIER_ORDER[a.priorityTier] || 3) - (TIER_ORDER[b.priorityTier] || 3)
);

// Build alert body
const SEP = '─'.repeat(50);
let body = `⚡ REPLY ALERT — ${staleReplies.length} unanswered repl${staleReplies.length === 1 ? 'y' : 'ies'}\n`;
body += `${'='.repeat(50)}\n\n`;
body += `These leads replied today and have been waiting 2+ hours.\n`;
body += `Respond NOW to maintain conversion momentum.\n\n`;

for (const r of staleReplies) {
  body += `${r.priorityTier} [Score ${r.leadScore}/10] ${r.businessName}\n`;
  body += `  Waiting: ${r.elapsedStr} since reply\n`;
  body += `  Email: ${r.email}\n`;
  body += `  Reply type: ${r.replyType}\n`;
  body += `  They said: ${r.replySummary}\n`;
  body += `  CRM status: ${r.status}\n\n`;
}

body += SEP + '\n';
body += `Open Gmail and respond before these leads go cold.\n`;

const subjectLine = staleReplies.length === 1
  ? `⚡ ${staleReplies[0].businessName} replied ${staleReplies[0].elapsedStr} ago — respond now`
  : `⚡ ${staleReplies.length} leads replied hours ago — respond now`;

return [{
  json: {
    hasStaleReplies: true,
    count: staleReplies.length,
    alertBody: body,
    subjectLine
  }
}];
